import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"Existing platform capabilities","description":"","frontmatter":{"docLocale":"en","counterpart":"/guides/platform","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/guides/platform.md","filePath":"en/guides/platform.md"}'),i={name:"en/guides/platform.md"};function o(n,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="existing-platform-capabilities" tabindex="-1">Existing platform capabilities <a class="header-anchor" href="#existing-platform-capabilities" aria-label="Permalink to &quot;Existing platform capabilities&quot;">​</a></h1><p>Choose the real interfaces for current Lab Word Platform Core. Start the Node service with <a href="./server-foundation">service foundation</a>. Development needs no Docker, Rust or external database.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/auth/session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/openapi.json</span></span></code></pre></div><p>Anonymous session returns 401. OpenAPI returns the complete retained Node contract with the title <code>Lab Word API</code>. See identity, memberships, API keys, audit, idempotency, limits and files in the <a href="./server-platform">platform guide</a>. See byte storage and business references in the <a href="./server-files">file guide</a>. Lab assets, World writes and device programs use this service.</p><p>Core does not import Lab. Core owns role management. <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/docs/adr/0008-full-lab-access-for-users-and-agents.md" target="_blank" rel="noreferrer">ADR 0008</a> defines full Lab access for users and valid <code>lab:full</code> Agents. Lab owns its business validator, references and publication callback.</p><p>The generated <a href="./../reference/api">API</a> and <a href="./../reference/config">configuration</a> come from the official Node source. Retired Rust and deployment source is preserved at <code>legacy-rust-final</code>. Current source, commands and the official SDK use Node. Final CI and integration determine Migration Gate completion.</p><p>Run <code>pnpm test:server</code> from the repository root for real Node HTTP, capabilities and transaction recovery. Frontend tests use MSW at HTTP. They do not prove storage integration. Choose affected interfaces with the <a href="./../testing/feedback-loop">testing guide</a>. See <a href="./server-operations">operations</a> for backup/restore/password recovery and <a href="./server-web">Web hosting</a> for production same-origin access.</p><hr><p>Source version：<code>5bc2e40dbe78</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/5bc2e40dbe78e853bcab2fd1c986ac39edee52b4/docs/guides/platform.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,9)])])}const u=a(i,[["render",o]]);export{h as __pageData,u as default};
